package com.bautruc.ecommerce.commerce.api;
import com.bautruc.ecommerce.commerce.api.request.CheckoutRequest;import com.bautruc.ecommerce.commerce.api.response.CheckoutResponse;import com.bautruc.ecommerce.commerce.application.*;import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.ApiResponse;import com.bautruc.ecommerce.common.time.BusinessClock;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController public class CheckoutController{private final CheckoutApplicationService checkout;private final BusinessClock clock;public CheckoutController(CheckoutApplicationService c,BusinessClock b){checkout=c;clock=b;}@PostMapping("/api/v1/checkout")public ApiResponse<CheckoutResponse> checkout(@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody CheckoutRequest request){return ApiResponse.success(checkout.checkout(key,request),null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
